class Solution { public:long long maxScore(vector<int>& nums1,vector<int>& nums2,int k){vector<int> order(nums1.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return nums2[a]>nums2[b];});priority_queue<int,vector<int>,greater<int>> heap;long long sum=0,answer=0;for(int index:order){heap.push(nums1[index]);sum+=nums1[index];if((int)heap.size()>k){sum-=heap.top();heap.pop();}if((int)heap.size()==k)answer=max(answer,sum*nums2[index]);}return answer;} };
